dashboard.definition:
{
  "title": "Activité des comptes AD et détection de menaces",
  "description": "Activité d'administration quotidienne d'Active Directory (création/suppression/désactivation de comptes, réinitialisations de mot de passe, verrouillages, changements de groupes privilégiés) et détection de techniques d'attaque courantes : password spray, Kerberoasting, DCSync, effacement du journal d'audit, altération de la politique d'audit, modifications DSRM et SID History. Basé sur les événements de sécurité Windows des contrôleurs de domaine.",
  "inputs": {
    "input_global_trp": {
      "type": "input.timerange",
      "title": "Période",
      "options": {
        "token": "global_time",
        "defaultValue": "-7d@h,now"
      }
    }
  },
  "defaults": {},
  "visualizations": {
    "viz_1": {
      "type": "splunk.singlevalue",
      "title": "Comptes créés",
      "dataSources": {
        "primary": "ds_1"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_security_events` EventCode IN (4720)",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_2": {
      "type": "splunk.singlevalue",
      "title": "Comptes supprimés",
      "dataSources": {
        "primary": "ds_2"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_security_events` EventCode IN (4726)",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_3": {
      "type": "splunk.singlevalue",
      "title": "Comptes désactivés",
      "dataSources": {
        "primary": "ds_3"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_security_events` EventCode IN (4725)",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_4": {
      "type": "splunk.singlevalue",
      "title": "Comptes activés",
      "dataSources": {
        "primary": "ds_4"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_security_events` EventCode IN (4722)",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_5": {
      "type": "splunk.singlevalue",
      "title": "Réinitialisations de mot de passe par des admins",
      "dataSources": {
        "primary": "ds_5"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_security_events` EventCode IN (4724)",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_6": {
      "type": "splunk.singlevalue",
      "title": "Verrouillages",
      "dataSources": {
        "primary": "ds_6"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 10
          },
          {
            "value": "#FFC300",
            "from": 10,
            "to": 50
          },
          {
            "value": "#B0413E",
            "from": 50
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_security_events` EventCode IN (4740)",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_7": {
      "type": "splunk.singlevalue",
      "title": "Changements de groupes privilégiés",
      "dataSources": {
        "primary": "ds_7"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#B0413E",
            "from": 1
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_security_events` `adx_normalize` | search is_group_event=1 | where match(group_name,\"(?i)^(`adx_priv_group_names`)(?![\\w -])\") | table _time action event_id target_user actor_user src_ip src_host dc",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_8": {
      "type": "splunk.singlevalue",
      "title": "Journal d'audit effacé / politique modifiée",
      "dataSources": {
        "primary": "ds_8"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#B0413E",
            "from": 1
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_security_events` EventCode IN (1102,4719)",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_9": {
      "type": "splunk.column",
      "title": "Cycle de vie des comptes et événements d'authentification dans le temps",
      "dataSources": {
        "primary": "ds_9"
      },
      "options": {
        "legendDisplay": "bottom",
        "stackMode": "stacked"
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_security_events` `adx_normalize` | search event_id IN (4720,4722,4723,4724,4725,4726,4738,4740,4767,4781) | lookup adx_event_catalog event_id OUTPUT action | timechart count by action",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_10": {
      "type": "splunk.table",
      "title": "Changements d'appartenance aux groupes privilégiés",
      "dataSources": {
        "primary": "ds_10"
      },
      "options": {
        "count": 10,
        "wrap": true
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_security_events` `adx_normalize` | search is_group_event=1 | where match(group_name,\"(?i)^(`adx_priv_group_names`)(?![\\w -])\") | lookup adx_event_catalog event_id OUTPUT action | rename actor_user as changed_by, target_user as member | sort - _time | table _time action group_name member changed_by dc | rename _time as \"Heure\", action as \"Action\", group_name as \"Groupe\", member as \"Membre\", changed_by as \"Modifié par\", dc as \"DC\"",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_11": {
      "type": "splunk.table",
      "title": "Événements critiques sur les contrôles de sécurité",
      "dataSources": {
        "primary": "ds_11"
      },
      "options": {
        "count": 10,
        "wrap": true
      },
      "description": "Journal d'audit effacé (1102), politique d'audit modifiée (4719), mot de passe DSRM défini (4794), SID History ajouté (4765/4766).",
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_security_events` `adx_normalize` | search event_id IN (1102,4719,4794,4765,4766) | lookup adx_event_catalog event_id OUTPUT action severity | sort - _time | table _time action severity actor_user target_user dc | rename _time as \"Heure\", action as \"Action\", severity as \"Gravité\", actor_user as \"Acteur\", target_user as \"Compte cible\", dc as \"DC\"",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_12": {
      "type": "splunk.table",
      "title": "Réinitialisations de mot de passe par les administrateurs",
      "dataSources": {
        "primary": "ds_12"
      },
      "options": {
        "count": 8,
        "wrap": true
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_security_events` `adx_normalize` | search event_id=4724 | stats count, dc(target_user) as accounts, latest(_time) as last by actor_user | eval last=strftime(last,\"%Y-%m-%d %H:%M\") | sort - count | table actor_user count accounts last | rename actor_user as \"Acteur\", count as \"Nombre\", accounts as \"Comptes\", last as \"Dernière occurrence\"",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_13": {
      "type": "splunk.table",
      "title": "Verrouillages - principaux comptes et postes appelants",
      "dataSources": {
        "primary": "ds_13"
      },
      "options": {
        "count": 8,
        "wrap": true
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_security_events` `adx_normalize` | search event_id=4740 | stats count, values(src_host) as caller_computers, latest(_time) as last by target_user | eval last=strftime(last,\"%Y-%m-%d %H:%M\") | sort - count | table target_user count caller_computers last | rename target_user as \"Compte cible\", count as \"Nombre\", caller_computers as \"Postes appelants\", last as \"Dernière occurrence\"",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_14": {
      "type": "splunk.table",
      "title": "Comptes créés / supprimés / désactivés",
      "dataSources": {
        "primary": "ds_14"
      },
      "options": {
        "count": 8,
        "wrap": true
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_security_events` `adx_normalize` | search event_id IN (4720,4726,4725) | lookup adx_event_catalog event_id OUTPUT action | rename actor_user as by_admin | sort - _time | table _time action target_user by_admin dc | rename _time as \"Heure\", action as \"Action\", target_user as \"Compte cible\", by_admin as \"Par l'admin\", dc as \"DC\"",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_15": {
      "type": "splunk.table",
      "title": "Suspicions de password spray / force brute",
      "dataSources": {
        "primary": "ds_15"
      },
      "options": {
        "count": 8,
        "wrap": true
      },
      "description": "Une même source en échec sur de nombreux comptes distincts (seuil : macro adx_spray_threshold).",
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_security_events` (EventCode=4625 OR EventCode=4771 OR (EventCode=4776 NOT Error_Code=0x0)) `adx_normalize` | stats count as attempts, dc(target_user) as accounts, min(_time) as first, max(_time) as last, values(target_user) as sample by src_ip src_host | where accounts>=`adx_spray_threshold` | eval sample=mvindex(sample,0,4), first=strftime(first,\"%Y-%m-%d %H:%M\"), last=strftime(last,\"%Y-%m-%d %H:%M\") | sort - accounts | table src_ip src_host attempts accounts first last sample | rename src_ip as \"IP source\", src_host as \"Hôte source\", attempts as \"Tentatives\", accounts as \"Comptes\", first as \"Première\", last as \"Dernière occurrence\", sample as \"Exemples\"",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_16": {
      "type": "splunk.table",
      "title": "Causes des échecs de connexion",
      "dataSources": {
        "primary": "ds_16"
      },
      "options": {
        "count": 8,
        "wrap": true
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_security_events` EventCode=4625 | eval code=coalesce(Sub_Status, SubStatus, Status) | lookup adx_failure_codes code OUTPUT reason | stats count by code reason | sort - count | table code reason count | rename code as \"Code\", reason as \"Raison\", count as \"Nombre\"",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_17": {
      "type": "splunk.table",
      "title": "Suspicions de Kerberoasting (tickets de service RC4 pour de nombreux SPN)",
      "dataSources": {
        "primary": "ds_17"
      },
      "options": {
        "count": 8,
        "wrap": true
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_security_events` EventCode=4769 `adx_normalize` | eval enc=coalesce(TicketEncryptionType, Ticket_Encryption_Type), svc=coalesce(ServiceName, Service_Name) | where enc=\"0x17\" AND lower(svc)!=\"krbtgt\" AND substr(svc,-1)!=\"$$\" | stats dc(svc) as spns, count, values(svc) as sample by target_user src_ip | where spns>=5 | eval sample=mvindex(sample,0,4) | sort - spns | table target_user src_ip spns count sample | rename target_user as \"Compte cible\", src_ip as \"IP source\", spns as \"SPN distincts\", count as \"Nombre\", sample as \"Exemples\"",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_18": {
      "type": "splunk.table",
      "title": "Suspicions de DCSync (droits de réplication utilisés par un compte non-DC)",
      "dataSources": {
        "primary": "ds_18"
      },
      "options": {
        "count": 8,
        "wrap": true
      },
      "description": "Nécessite « Audit Directory Service Access » et une SACL à la racine du domaine ; les comptes machines (DC$) sont exclus.",
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_security_events` EventCode=4662 (\"1131f6aa-9c07-11d1-f79f-00c04fc2dcd2\" OR \"1131f6ad-9c07-11d1-f79f-00c04fc2dcd2\" OR \"89e95b76-444d-4c62-991a-0facbeda640c\") `adx_normalize` | where substr(actor_user,-1)!=\"$$\" | stats count, latest(_time) as last by actor_user dc | eval last=strftime(last,\"%Y-%m-%d %H:%M\") | table actor_user dc count last | rename actor_user as \"Acteur\", dc as \"DC\", count as \"Nombre\", last as \"Dernière occurrence\"",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    }
  },
  "dataSources": {
    "ds_1": {
      "type": "ds.search",
      "name": "Comptes créés",
      "options": {
        "query": "`adx_security_events` EventCode IN (4720) | stats count",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_2": {
      "type": "ds.search",
      "name": "Comptes supprimés",
      "options": {
        "query": "`adx_security_events` EventCode IN (4726) | stats count",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_3": {
      "type": "ds.search",
      "name": "Comptes désactivés",
      "options": {
        "query": "`adx_security_events` EventCode IN (4725) | stats count",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_4": {
      "type": "ds.search",
      "name": "Comptes activés",
      "options": {
        "query": "`adx_security_events` EventCode IN (4722) | stats count",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_5": {
      "type": "ds.search",
      "name": "Réinitialisations de mot de passe par des admins",
      "options": {
        "query": "`adx_security_events` EventCode IN (4724) | stats count",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_6": {
      "type": "ds.search",
      "name": "Verrouillages",
      "options": {
        "query": "`adx_security_events` EventCode IN (4740) | stats count",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_7": {
      "type": "ds.search",
      "name": "Changements de groupes privilégiés",
      "options": {
        "query": "`adx_security_events` `adx_normalize` | search is_group_event=1 | where match(group_name,\"(?i)^(`adx_priv_group_names`)(?![\\w -])\") | stats count",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_8": {
      "type": "ds.search",
      "name": "Journal d'audit effacé / politique modifiée",
      "options": {
        "query": "`adx_security_events` EventCode IN (1102,4719) | stats count",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_9": {
      "type": "ds.search",
      "name": "Cycle de vie des comptes et événements d'authentification dans le temps",
      "options": {
        "query": "`adx_security_events` `adx_normalize` | search event_id IN (4720,4722,4723,4724,4725,4726,4738,4740,4767,4781) | lookup adx_event_catalog event_id OUTPUT action | timechart count by action",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_10": {
      "type": "ds.search",
      "name": "Changements d'appartenance aux groupes privilégiés",
      "options": {
        "query": "`adx_security_events` `adx_normalize` | search is_group_event=1 | where match(group_name,\"(?i)^(`adx_priv_group_names`)(?![\\w -])\") | lookup adx_event_catalog event_id OUTPUT action | rename actor_user as changed_by, target_user as member | sort - _time | table _time action group_name member changed_by dc | rename _time as \"Heure\", action as \"Action\", group_name as \"Groupe\", member as \"Membre\", changed_by as \"Modifié par\", dc as \"DC\"",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_11": {
      "type": "ds.search",
      "name": "Événements critiques sur les contrôles de sécurité",
      "options": {
        "query": "`adx_security_events` `adx_normalize` | search event_id IN (1102,4719,4794,4765,4766) | lookup adx_event_catalog event_id OUTPUT action severity | sort - _time | table _time action severity actor_user target_user dc | rename _time as \"Heure\", action as \"Action\", severity as \"Gravité\", actor_user as \"Acteur\", target_user as \"Compte cible\", dc as \"DC\"",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_12": {
      "type": "ds.search",
      "name": "Réinitialisations de mot de passe par les administrateurs",
      "options": {
        "query": "`adx_security_events` `adx_normalize` | search event_id=4724 | stats count, dc(target_user) as accounts, latest(_time) as last by actor_user | eval last=strftime(last,\"%Y-%m-%d %H:%M\") | sort - count | table actor_user count accounts last | rename actor_user as \"Acteur\", count as \"Nombre\", accounts as \"Comptes\", last as \"Dernière occurrence\"",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_13": {
      "type": "ds.search",
      "name": "Verrouillages - principaux comptes et postes appelants",
      "options": {
        "query": "`adx_security_events` `adx_normalize` | search event_id=4740 | stats count, values(src_host) as caller_computers, latest(_time) as last by target_user | eval last=strftime(last,\"%Y-%m-%d %H:%M\") | sort - count | table target_user count caller_computers last | rename target_user as \"Compte cible\", count as \"Nombre\", caller_computers as \"Postes appelants\", last as \"Dernière occurrence\"",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_14": {
      "type": "ds.search",
      "name": "Comptes créés / supprimés / désactivés",
      "options": {
        "query": "`adx_security_events` `adx_normalize` | search event_id IN (4720,4726,4725) | lookup adx_event_catalog event_id OUTPUT action | rename actor_user as by_admin | sort - _time | table _time action target_user by_admin dc | rename _time as \"Heure\", action as \"Action\", target_user as \"Compte cible\", by_admin as \"Par l'admin\", dc as \"DC\"",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_15": {
      "type": "ds.search",
      "name": "Suspicions de password spray / force brute",
      "options": {
        "query": "`adx_security_events` (EventCode=4625 OR EventCode=4771 OR (EventCode=4776 NOT Error_Code=0x0)) `adx_normalize` | stats count as attempts, dc(target_user) as accounts, min(_time) as first, max(_time) as last, values(target_user) as sample by src_ip src_host | where accounts>=`adx_spray_threshold` | eval sample=mvindex(sample,0,4), first=strftime(first,\"%Y-%m-%d %H:%M\"), last=strftime(last,\"%Y-%m-%d %H:%M\") | sort - accounts | table src_ip src_host attempts accounts first last sample | rename src_ip as \"IP source\", src_host as \"Hôte source\", attempts as \"Tentatives\", accounts as \"Comptes\", first as \"Première\", last as \"Dernière occurrence\", sample as \"Exemples\"",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_16": {
      "type": "ds.search",
      "name": "Causes des échecs de connexion",
      "options": {
        "query": "`adx_security_events` EventCode=4625 | eval code=coalesce(Sub_Status, SubStatus, Status) | lookup adx_failure_codes code OUTPUT reason | stats count by code reason | sort - count | table code reason count | rename code as \"Code\", reason as \"Raison\", count as \"Nombre\"",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_17": {
      "type": "ds.search",
      "name": "Suspicions de Kerberoasting (tickets de service RC4 pour de nombreux SPN)",
      "options": {
        "query": "`adx_security_events` EventCode=4769 `adx_normalize` | eval enc=coalesce(TicketEncryptionType, Ticket_Encryption_Type), svc=coalesce(ServiceName, Service_Name) | where enc=\"0x17\" AND lower(svc)!=\"krbtgt\" AND substr(svc,-1)!=\"$$\" | stats dc(svc) as spns, count, values(svc) as sample by target_user src_ip | where spns>=5 | eval sample=mvindex(sample,0,4) | sort - spns | table target_user src_ip spns count sample | rename target_user as \"Compte cible\", src_ip as \"IP source\", spns as \"SPN distincts\", count as \"Nombre\", sample as \"Exemples\"",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_18": {
      "type": "ds.search",
      "name": "Suspicions de DCSync (droits de réplication utilisés par un compte non-DC)",
      "options": {
        "query": "`adx_security_events` EventCode=4662 (\"1131f6aa-9c07-11d1-f79f-00c04fc2dcd2\" OR \"1131f6ad-9c07-11d1-f79f-00c04fc2dcd2\" OR \"89e95b76-444d-4c62-991a-0facbeda640c\") `adx_normalize` | where substr(actor_user,-1)!=\"$$\" | stats count, latest(_time) as last by actor_user dc | eval last=strftime(last,\"%Y-%m-%d %H:%M\") | table actor_user dc count last | rename actor_user as \"Acteur\", dc as \"DC\", count as \"Nombre\", last as \"Dernière occurrence\"",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    }
  },
